(628, 447, NULL, \'<p>Kebolehan menganalisis dan mencari punca masalah.<br />\\n(Kebolehan dan keupayaan meneliti, mentafsir dan mencerakin fakta, situasi, kejadian dan arah aliran kepada bentuk yang mudah dan realistik serta mengemukakan cadangan tindakan yang sesuai.)</p>\', NULL, NULL, \'2024-11-27 16:17:35\', \'2024-11-27 16:17:35\', NULL),
(629, 447, NULL, \'<p>Kebolehan menyelesaikan masalah dan membuat keputusan (Kebolehan mengenal pasti masalah dalam organisasi dan mengemukakan pelbagai alternatif dan menyelesaikannya secara berkesan berdasarkan ilmu pengetahuan dan kemahiran dimiliki.)</p>\', NULL, NULL, \'2024-11-27 16:18:41\', \'2024-11-27 16:18:41\', NULL),
(630, 447, NULL, \'<p>Kebolehan melakukan kerja dengan sistematik dan merekodkan kerja</p>\', NULL, NULL, \'2024-11-27 16:19:47\', \'2024-11-27 16:19:47\', NULL),
(631, 447, NULL, \'<p>Komitmen terhadap kerja (Mempunyai komitmen dan daya usaha yang tinggi, berpandangan jauh dan mendorong ke arah peningkatan budaya kecemerlangan organisasi secara keseluruhannya.)</p>\', NULL, NULL, \'2024-11-27 16:21:15\', \'2024-11-27 16:21:15\', NULL),
(632, 447, NULL, \'<p>Memotivasikan rakan sekerja supaya lebih bertungkus-lumus dalam kerja harian (cth: selalu bertegur sapa sesama rakan sekerja, menegur kesilapan rakan sekerja)</p>\', NULL, NULL, \'2024-11-27 16:22:10\', \'2024-11-27 16:22:10\', NULL),
