(650, 452, NULL, \'<p>Sentiasa bersopan dan menghormati mahupun rakan sekerja atau pegawai atasan dalam segi percakapan, tingkah laku, gerak-geri badan. (cth: tidak bergaduh atau sengaja mencederakan rakan sekerja, tidak berkelakuan buruk, tidak bersikap kasar atau berbahasa kesat)</p>\', NULL, NULL, \'2024-11-29 12:28:35\', \'2024-11-29 12:28:35\', NULL),
(651, 453, NULL, \'<p>Akan berinisiatif untuk mendapatkan kepastian apabila arahan atau tugasan yang diberi oleh pegawai atasan tidak jelas atau ada kesilapan.</p>\', NULL, NULL, \'2024-11-29 12:29:47\', \'2024-11-29 12:29:47\', NULL),
(652, 453, NULL, \'<p>Mengikuti arahan dari pegawai atasan dengan menerima informasi dengan jelas dan tepat serta persefahaman yang sama dalam kerja.</p>\', NULL, NULL, \'2024-11-29 12:30:46\', \'2024-11-29 12:30:46\', NULL),
(653, 454, NULL, \'<p>Sudi membantu dan memberi pertolongan. Mempunyai semangat kerjasama antara rakan sekerja dan pegawai atasan dan melaksanakan tugas secara berpasukan dan mewujudkan hubungan yang harmoni dan mesra.</p>\', NULL, NULL, \'2024-11-29 12:31:57\', \'2024-11-29 12:31:57\', NULL),
(654, 454, NULL, \'<p>Sudi menerima tugasan tambahan atau di luar bidang.</p>\', NULL, NULL, \'2024-11-29 12:33:04\', \'2024-11-29 12:33:04\', NULL),
(655, 468, NULL, \'<p>Tidak dapat melakukan kerja walaupun sudah dibimbing</p>\', NULL, NULL, \'2024-11-29 12:43:36\', \'2024-11-29 12:43:36\', NULL),
(656, 468, NULL, \'<p>Dapat melakukan kerja jika telah dibimbing oleh orang lain</p>\', NULL, NULL, \'2024-11-29 12:43:43\', \'2024-11-29 12:43:43\', NULL),
(657, 468, NULL, \'<p>Boleh melakukan kerja dengan baik dan memerlukan bimbingan kecil sahaja</p>\', NULL, NULL, \'2024-11-29 12:43:51\', \'2024-11-29 12:43:51\', NULL),
