(667, 471, NULL, \'<p>Kebolehan menganalisis dan mencari punca masalah.<br />\\n(Kebolehan dan keupayaan meneliti, mentafsir dan mencerakin fakta, situasi, kejadian dan arah aliran kepada bentuk yang mudah dan realistik serta mengemukakan cadangan tindakan yang sesuai.)</p>\', NULL, NULL, \'2024-12-03 17:45:46\', \'2024-12-03 17:45:46\', NULL),
(668, 471, NULL, \'<p>Kebolehan menyelesaikan masalah dan membuat keputusan (Kebolehan mengenal pasti masalah dalam organisasi dan mengemukakan pelbagai alternatif dan menyelesaikannya secara berkesan berdasarkan ilmu pengetahuan dan kemahiran dimiliki.</p>\', NULL, NULL, \'2024-12-03 17:46:59\', \'2024-12-03 17:46:59\', NULL),
(669, 471, NULL, \'<p>Kebolehan melakukan kerja dengan sistematik dan merekodkan kerja</p>\', NULL, NULL, \'2024-12-03 17:50:26\', \'2024-12-03 17:50:26\', NULL),
(670, 471, NULL, \'<p>Komitmen terhadap kerja (Mempunyai komitmen dan daya usaha yang tinggi, berpandangan jauh dan mendorong ke arah peningkatan budaya kecemerlangan organisasi secara keseluruhannya.)</p>\', NULL, NULL, \'2024-12-03 17:57:17\', \'2024-12-03 17:57:17\', NULL),
(671, 471, NULL, \'<p>Memotivasikan rakan sekerja supaya lebih bertungkus-lumus dalam kerja harian (cth: selalu bertegur sapa sesama rakan sekerja, menegur kesilapan rakan sekerja)</p>\', NULL, NULL, \'2024-12-03 17:58:12\', \'2024-12-03 17:58:12\', NULL),
(672, 472, NULL, \'<p>Menyempurnakan tugasan yang diberi dalam tempoh masa yang ditetapkan.</p>\', NULL, NULL, \'2024-12-03 17:59:21\', \'2024-12-03 17:59:21\', NULL),
(673, 472, NULL, \'<p>Cepat bertindak/bergerak dan tidak menolak tanggungjawab kerja dengan berpura-pura/berdiam diri walaupun tahu apa cara untuk membuat kerja/menyelesaikan masalah.</p>\', NULL, NULL, \'2024-12-03 18:00:28\', \'2024-12-03 18:00:28\', NULL);');
