(66, 36, \'<p><strong>Kepimpinan</strong></p>\', NULL, NULL, \'2024-11-08 17:18:33\', \'2024-11-08 17:18:33\', NULL),
(67, 36, \'<p><strong>Produktiviti</strong></p>\', NULL, NULL, \'2024-11-08 17:18:33\', \'2024-11-08 17:19:11\', NULL),
(68, 36, \'<p><strong>Pengetahuan Kerja</strong></p>\', NULL, NULL, \'2024-11-08 17:18:33\', \'2024-11-08 17:19:20\', NULL),
(69, 36, \'<p><strong>Housekeeping</strong></p>\', NULL, NULL, \'2024-11-08 17:18:33\', \'2024-11-08 17:19:33\', NULL),
(70, 36, \'<p><strong>Sikap</strong></p>\', NULL, NULL, \'2024-11-08 17:18:33\', \'2024-11-08 17:19:42\', NULL),
(71, 36, \'<p><strong>Disiplin/ Tatatertib</strong></p>\', NULL, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:18:34\', NULL),
(72, 36, \'<p><strong>Komunikasi</strong></p>\', NULL, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:19:55\', NULL),
(73, 36, \'<p><strong>Bekerjasama</strong></p>\', NULL, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:18:34\', NULL),
(74, 37, \'<p>Technical Drawing Skills - Proficiency in creating detailed, accurate, and clear technical drawings using tools such as AutoCAD, SolidWorks, or other drafting software. - Ability to understand and interpret engineering drawings, specifications, and technical documentation.</p>\', 1, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:20:11\', NULL),
(75, 37, \'<p>CAD / CAM Software Proficiency - Familiarity with CAD / CAM software is crucial. This includes knowledge of AutoCAD, SolidWorks, CypCut, Tubest, MasterCAM.</p>\', 2, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:20:17\', NULL),
(76, 37, \'<p>Geometry and Mathematics - Strong mathematical skills and a good understanding of geometry, including the ability to perform calculations related to dimensions, angles, and tolerances.</p>\', 3, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:18:34\', NULL),
(77, 37, \'<p>Knowledge of Materials and Manufacturing Processes - Understanding of various materials and their properties, as well as knowledge of different manufacturing processes, including machining, welding, and assembly.</p>\', 4, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:20:24\', NULL),
(78, 37, \'<p>Attention to Detail - The ability to pay close attention to detail is essential for creating accurate and error-free technical drawings.</p>\', 5, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:20:30\', NULL),
(79, 37, \'<p>Problem-Solving Skills - The capability to identify and solve problems related to design and drafting, including the ability to suggest improvements and optimizations.</p>\', 6, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:20:35\', NULL),
(80, 37, \'<p>Time Management - Efficient time management to meet project deadlines and handle multiple tasks simultaneously.</p>\', 7, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:20:41\', NULL),
(81, 37, \'<p>3D Modeling Skills - Proficiency in creating 3D models of mechanical components and assemblies to provide a comprehensive view of the design.</p>\', 8, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:18:34\', NULL),
(82, 37, \'<p>Continuous Learning - A willingness to stay updated with the latest advancements in CAD software, industry standards, and manufacturing technologies.</p>\', 9, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:18:34\', NULL),
(83, 37, \'<p>Collaboration and Teamwork - Ability to work collaboratively with engineers, architects, and other professionals as part of a multidisciplinary team.</p>\', 10, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:20:49\', NULL),
(84, 39, \'<p>Sila nyatakan kelebihan pekerja.</p>\', 1, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:22:22\', NULL),
(85, 39, \'<p>Sila nyatakan kelemahan pekerja.</p>\', 2, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:18:34\', NULL),
(86, 39, \'<p>Faktor-faktor yang perlu diberi perhatian untuk dipertingkatkan/diperbaiki.</p>\', 3, NULL, \'2024-11-08 17:18:34\', \'2024-11-08 17:22:57\', NULL),
