(134, 58, \'<p>Pengetahuan dalam wiring 3 phase 415V, single phase 240V dan direct current 24VDC</p>\', NULL, NULL, \'2024-11-09 15:03:27\', \'2024-11-09 15:03:27\', NULL),
(135, 58, \'<p>Pengetahuan dalam control panel general wiring seperti wiring DOL, star delta, forward/reverse, auto trans</p>\', NULL, NULL, \'2024-11-09 15:03:43\', \'2024-11-09 15:03:43\', NULL),
(136, 58, \'<p>Pengetahuan dalam pneumatic valve system</p>\', NULL, NULL, \'2024-11-09 15:03:52\', \'2024-11-09 15:03:52\', NULL),
(137, 58, \'<p>Pengetahuan dalam bidang color sorter (seperti setting beras, camera dan wiper), robot, auto packer dan rotary packer</p>\', NULL, NULL, \'2024-11-09 15:04:01\', \'2024-11-09 15:04:01\', NULL),
(138, 58, \'<p>Lengkapkan pemasangan mekanikal/elektrik, pemasangan dan ujian peralatan dalam tarikh yang ditetapkan seperti contoh pengetahuan dalam pemasangan rotary packer (RPM-100, RTP-1000)</p>\', NULL, NULL, \'2024-11-09 15:04:11\', \'2024-11-09 15:04:11\', NULL),
(139, 58, \'<p>Dapat memasang produk mengikut lukisan elektrik/mekanikal dan arahan kerja seperti faham diagram dengan boleh set untuk timbangan mesin</p>\', NULL, NULL, \'2024-11-09 15:04:19\', \'2024-11-09 15:04:19\', NULL),
(140, 58, \'<p>Pemasangan cable yang betul dan penggunaan cable lug supaya tidak longgar dan tersusun kemas</p>\', NULL, NULL, \'2024-11-09 15:04:31\', \'2024-11-09 15:04:37\', NULL),
(141, 58, \'<p>Mampu menyelesaikan masalah mesin dan menjalankan pembaikan dan pengubahsuaian jika perlu (troubleshoot machine)</p>\', NULL, NULL, \'2024-11-09 15:04:45\', \'2024-11-09 15:04:45\', NULL),
(142, 58, \'<p>Boleh bekerja di outsite dan jalankan kerja pemasangan dan servis</p>\', NULL, NULL, \'2024-11-09 15:04:53\', \'2024-11-09 15:04:53\', NULL),
